def menu_body(cat,rows=None,heading=None,description=None,path=None,page_number=1):
 rows=rows if rows is not None else [p for p in P if cat=="Все меню" or p["category"]==cat]
 path=path or url(cat);heading=heading or ("Меню кафе в Севастополе" if cat=="Все меню" else cat+" в Севастополе — меню и доставка")
 description=description or "Фото, состав, цены и варианты блюд из меню Wisteria cafe. Заказ подтверждает сотрудник кафе."
 cards="".join(static_card(p)for p in rows[(page_number-1)*24:page_number*24])
 pagination=menu_pagination(path,len(rows),page_number)
 exclusions=''.join(f'<label><input type="checkbox" data-exclude value="{v}">{v}</label>' for v in ['Молоко','Яйца','Глютен','Соя','Рыба','Ракообразные','Моллюски','Орехи','Кунжут','Горчица'])
 if path==url(cat) and page_number==1:
  heading='Меню со вкусом' if cat=='Все меню' else cat
  if cat=='Все меню':description='От первого кофе до любимого десерта. Выбирайте в своём ритме.'
 occasions='<div class="catalog-occasions" role="group" aria-label="Подборки по вашему настроению">'+''.join(f'<button class="occasion-button {"active" if key=="all" else ""}" data-occasion="{key}" aria-pressed="{"true" if key=="all" else "false"}">{label}</button>' for key,label in [('all','Всё меню'),('breakfast','На завтрак'),('lunch','На обед'),('coffee','К кофе'),('plant','Растительное')])+'</div>' if cat=='Все меню' else ''
 return intro(heading, description, botanical=True)+f'''<div class="container catalog-layout page-end"><aside class="sidebar" aria-label="Категории меню">{''.join(f'<a class="{"active" if c==cat else ""}" aria-current="{"page" if c==cat else "false"}" href="{url(c)}"><span>{c}</span><small class="category-count">{len(P) if c=="Все меню" else sum(1 for p in P if p["category"]==c)}</small></a>' for c in categories)}</aside><div class="catalog-main">{occasions}<div class="catalog-toolbar"><label for="search"><span>Найти в меню</span><input id="search" type="search" placeholder="Блюдо или ингредиент"></label><label for="budget"><span>Цена в меню</span><select id="budget"><option value="0">Любая цена</option><option value="300">До 300 ₽</option><option value="500">До 500 ₽</option><option value="700">До 700 ₽</option></select></label><label for="sort"><span>Порядок блюд</span><select id="sort"><option value="default">Как в меню</option><option value="price-up">Сначала дешевле</option><option value="price-down">Сначала дороже</option><option value="calories">Ккал на 100 г ↑</option></select></label></div><details class="menu-guide"><summary>О составе, ценах и выборе блюд</summary><p>Фото открывает быстрый просмотр. «От» — минимальная цена опубликованного варианта. Вес и КБЖУ — по данным кафе. Полный состав и варианты доступны в карточке блюда.</p></details><details class="filterbox"><summary>Состав, аллергены и избранное</summary><div class="checks"><label><input type="checkbox" id="favorites-only">Только избранное</label><label><input type="checkbox" id="composition-only">Есть опубликованный состав</label></div><p class="small">Исключить аллергены, найденные в опубликованном составе:</p><div class="checks">{exclusions}</div><p class="small muted">Фильтр скрывает блюда без опубликованного состава. Он не учитывает все составные ингредиенты, соусы и возможные следы и не гарантирует безопасность при аллергии.</p><button id="reset-filters" class="smallbtn">Сбросить фильтры</button></details><div class="active-filters" id="active-filters" aria-live="polite"></div><div class="notice" id="filter-warning" hidden>Это фильтр по опубликованным ингредиентам. Для заказа при аллергии нужна проверка кафе.</div><div class="sectionhead"><p id="result-count" class="small muted" role="status">{len(rows)} позиций</p><a href="/allergens/" class="link small">Как читать аллергены</a></div><div class="cards" id="catalog-cards">{cards}</div><div class="loadmore"><button class="btn light" id="load-more">Показать ещё блюда</button></div><noscript><p>Блюда и страницы меню доступны по ссылкам. Для корзины и фильтров включите JavaScript.</p></noscript>{pagination}</div></div>'''
def menu_pagination(path,count,current=1):
 pages=(count+23)//24
 return '<nav class="order-actions" aria-label="Страницы меню">'+''.join(f'<a class="btn light" href="{path if n==1 else path.rstrip("/")+"/page/"+str(n)+"/"}"'+(' aria-current="page"'if n==current else '')+f'>Страница {n}</a>'for n in range(1,pages+1))+'</nav>'if pages>1 else ''
def menu_page(path,cat,row,rows):
 title=row.get('title',cat+' — доставка в Севастополе');desc=row.get('description',cat+' Wisteria cafe: фото, состав и цены. Доставка и самовывоз в Севастополе.')
 attrs=f'data-category="{E(cat)}"'+(f' data-source-path="{E(path)}"'if path in LEAF_CONTENT and not row.get('scopeCategory') else '')+(f' data-legacy-source-path="{E(path)}"'if path in LEAF_CONTENT else '')
 related=[(v,re.split(r' в Севастополе| — ',LEAF_CONTENT.get(v,{}).get('h1',v.strip('/')))[0])for v in row.get('related',[])if isinstance(v,str)]
 # Each aggregate exposes its original subcategories as real links.
 if path not in LEAF_CONTENT:
  related+=[('/'+urllib.parse.urlsplit(source).path.strip('/'),re.split(r' в Севастополе| — ',LEAF_CONTENT.get('/'+urllib.parse.urlsplit(source).path.strip('/'),{}).get('h1',source.rsplit('/',1)[-1]))[0])for source in dict.fromkeys(p['source']for p in rows)]
 related=list(dict.fromkeys(related))
 body=menu_body(cat,rows,row.get('h1'),row.get('intro'),path)+copy_block(row,related+[(url('Все меню'),'Всё меню'),('/dostavkasevastopol','Доставка и самовывоз')])
 page(path,title,desc,body,attrs,kind='menu',rows=rows[:24])
 for n in range(2,(len(rows)+23)//24+1):
  pagepath=path.rstrip('/')+'/page/'+str(n)+'/'
  page(pagepath,title+f' — страница {n}',desc+f' Страница {n}.',menu_body(cat,rows,row.get('h1',cat)+f' — страница {n}',row.get('intro'),path,n),attrs+f' data-menu-page="{n}"',kind='menu',rows=rows[(n-1)*24:n*24])
for c in categories:
 path='/menu/'+(categories[c]+'/'if categories[c]else '')
 rows=[p for p in P if c=='Все меню' or p['category']==c]
 if preferred(path) in LEAF_CONTENT:continue
 menu_page(path,c,AGGREGATE_CONTENT.get(c,{}),rows)
for path,row in LEAF_CONTENT.items():
 rows=[p for p in P if urllib.parse.urlsplit(p['source']).path==path or any(urllib.parse.urlsplit(v).path==path for v in p.get('additionalSources',[]))]
 if rows:
  cat=rows[0]['category']
  if path in ['/kupitdesertysevastopol','/dostavka-tortov']:
   rows=[p for p in P if p['category']==cat];row={**AGGREGATE_CONTENT[cat],'scopeCategory':True}
  menu_page(path,cat,row,rows)
def clean_composition(p):
 return re.split(r'\n\s*(?:масса нетто|пищевая ценность|энергетическая ценность|вес|КБЖУ)\s*[:–-]?', p['composition'], maxsplit=1, flags=re.I)[0].strip()
def food_weight(p):
 if p['weight']: return re.sub(r'гр\.?','г',p['weight'].replace('+-','≈')).strip()
 m=re.search(r'Масса нетто\s*:\s*(\d+(?:[,.]\d+)?)\s*г',p['composition'],re.I)
 return m[1]+' г' if m else 'Вес / объём уточняется'
def nutrition_block(n):
 values=n.get('values',n.get('nutrition','').split('/'))
 if len(values)!=4 or n.get('needs_review')=='more_than_four_values_in_source':return ''
 return '<p class="small muted">'+E(n.get('context',''))+' · '+E(n.get('basis','по данным меню'))+'</p><div class="nutrition">'+''.join(f'<div><strong>{E(str(v))}</strong><small>{label}</small></div>' for v,label in zip(values,['ккал','белки, г','жиры, г','углеводы, г']))+'</div>'
def nutrition_html(p):
 variants=p.get('nutritionVariants',[])
 blocks=''.join(nutrition_block(n) for n in variants)
 note='Значения опубликованы для указанных вариантов. Соусы, замены и добавки уточняйте у кафе.'
